alter table public.carton_rewards add constraint carton_rewards_customer_id_fkey FOREIGN KEY (customer_id) REFERENCES customers(id) ON DELETE SET NULL;
alter table public.carton_rewards add constraint carton_rewards_item_id_fkey FOREIGN KEY (item_id) REFERENCES items(id) ON DELETE SET NULL;
alter table public.pickups add constraint pickups_status_check CHECK ((status = ANY (ARRAY['ready'::text, 'waiting'::text, 'picked'::text, 'cancelled'::text])));
alter table public.pickups add constraint pickups_code_key UNIQUE (code);
alter table public.pickup_items add constraint pickup_items_price_check CHECK ((price >= (0)::numeric));
alter table public.pickup_items add constraint pickup_items_qty_check CHECK ((qty > 0));
alter table public.admins add constraint admins_user_id_fkey FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE CASCADE;
alter table public.items add constraint items_price_check CHECK ((price >= (0)::numeric));
alter table public.items add constraint items_stock_check CHECK ((stock >= 0));
alter table public.items add constraint items_low_stock_check CHECK ((low_stock >= 0));
alter table public.items add constraint items_brand_id_fkey FOREIGN KEY (brand_id) REFERENCES brands(id) ON DELETE RESTRICT;
alter table public.customers add constraint customers_carton_credits_check CHECK ((carton_credits >= 0));
alter table public.customers add constraint customers_total_cartons_check CHECK ((total_cartons >= 0));
alter table public.customers add constraint customers_free_dozens_check CHECK ((free_dozens >= 0));
alter table public.carton_returns add constraint carton_returns_qty_check CHECK ((qty > 0));
alter table public.carton_returns add constraint carton_returns_customer_id_fkey FOREIGN KEY (customer_id) REFERENCES customers(id) ON DELETE SET NULL;
alter table public.carton_rewards add constraint carton_rewards_credits_used_check CHECK ((credits_used > 0));
alter table public.pickup_items add constraint pickup_items_pickup_id_fkey FOREIGN KEY (pickup_id) REFERENCES pickups(id) ON DELETE CASCADE;
alter table public.pickup_items add constraint pickup_items_item_id_fkey FOREIGN KEY (item_id) REFERENCES items(id) ON DELETE SET NULL;
alter table public.sales add constraint sales_total_check CHECK ((total >= (0)::numeric));
alter table public.sales add constraint sales_pickup_id_fkey FOREIGN KEY (pickup_id) REFERENCES pickups(id) ON DELETE SET NULL;
alter table public.sale_items add constraint sale_items_price_check CHECK ((price >= (0)::numeric));
alter table public.sale_items add constraint sale_items_qty_check CHECK ((qty > 0));
alter table public.sale_items add constraint sale_items_sale_id_fkey FOREIGN KEY (sale_id) REFERENCES sales(id) ON DELETE CASCADE;
alter table public.sale_items add constraint sale_items_item_id_fkey FOREIGN KEY (item_id) REFERENCES items(id) ON DELETE SET NULL;
alter table public.stock_log add constraint stock_log_stock_after_check CHECK ((stock_after >= 0));
alter table public.stock_log add constraint stock_log_item_id_fkey FOREIGN KEY (item_id) REFERENCES items(id) ON DELETE SET NULL;
alter table public.store_revision_public add constraint store_revision_public_id_check CHECK ((id = 1));
alter table public.roost_returns add constraint roost_returns_qty_check CHECK ((qty > 0));
alter table public.roost_returns add constraint roost_returns_credits_earned_check CHECK ((credits_earned >= 0));
alter table public.roost_credit_uses add constraint roost_credit_uses_credits_used_check CHECK ((credits_used > 0));
alter table public.roost_credit_uses add constraint roost_credit_uses_credit_value_check CHECK ((credit_value > (0)::numeric));
alter table public.roost_credit_uses add constraint roost_credit_uses_discount_amount_check CHECK ((discount_amount >= (0)::numeric));
alter table public.customer_comments add constraint customer_comments_comment_text_check CHECK ((length(TRIM(BOTH FROM comment_text)) > 0));
